@keyframes scToastLifecycle {
  0% { opacity:0; transform:translateY(6px) scale(.98); }
  12%,72% { opacity:1; transform:translateY(0) scale(1); }
  100% { opacity:0; transform:translateY(-3px) scale(1); }
}

@keyframes scToastFade {
  0% { opacity:0; }
  8%,78% { opacity:1; }
  100% { opacity:0; }
}

